INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM206XTKF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution to the equation $x^2 + 3x - 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring gives $x^2 + 3x - 28 = (x + 7)(x - 4) = 0$, so $x = -7$ or $x = 4$. The positive solution is $4$. The distractor $7$ results from a sign error when extracting the root from the factor $(x + 7)$, taking $7$ instead of $-7$. The distractor $-7$ is the negative root, which does not satisfy the condition of being positive. The distractor $14$ may result from an arithmetic error such as mistakenly doubling $7$ or misapplying the quadratic formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20YZBDZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $p$ is defined by $p(x) = -3(x - 5)^2(x + 2)$. As $x$ increases without bound, which of the following best describes the end behavior of $p(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$p(x)$ increases without bound."},{"key":"B","text":"$p(x)$ decreases without bound."},{"key":"C","text":"$p(x)$ approaches $0$."},{"key":"D","text":"$p(x)$ approaches $-30$."}]$lyceon_json$::jsonb, 'B', NULL, E'Expanding the leading behavior: $p(x) = -3(x-5)^2(x+2)$. The highest-degree term comes from $-3 \\cdot x^2 \\cdot x = -3x^3$. Since the leading coefficient is $-3$ (negative) and the degree is $3$ (odd), as $x$ increases without bound, $p(x)$ decreases without bound (approaches $-\\infty$). The distractor stating $p(x)$ increases without bound neglects the negative leading coefficient. The distractor stating $p(x)$ approaches $0$ confuses this polynomial with a rational function that has a horizontal asymptote. The distractor stating $p(x)$ approaches $-30$ results from substituting a specific value such as $x = 0$ (giving $p(0) = -3(25)(2) = -150$) or misinterpreting a constant term as the long-run behavior.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21HIJCS', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A bakery sells muffins for $p$ dollars each and scones for $q$ dollars each. If 3 muffins and 2 scones cost $\\$23$, and 1 muffin and 2 scones cost $\\$13$, what is the price, in dollars, of one muffin?', NULL, $lyceon_json$[{"key":"A","text":"$\\$3$"},{"key":"B","text":"$\\$4$"},{"key":"C","text":"$\\$10$"},{"key":"D","text":"$\\$5$"}]$lyceon_json$::jsonb, 'D', NULL, E'The system is $3p + 2q = 23$ and $p + 2q = 13$. Subtracting the second equation from the first eliminates $q$: $2p = 10$, so $p = 5$, and one muffin costs $\\$5$. The distractor $\\$3$ results from an arithmetic error such as computing $23 - 13 = 10$ and then dividing by $3$ instead of $2$. The distractor $\\$4$ is the price of one scone ($q = 4$), not one muffin, reflecting a misread of what the question asks. The distractor $\\$10$ comes from stopping at $2p = 10$ without dividing by the coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM233LSDR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A teacher records quiz scores for 11 students: 41, 55, 58, 62, 67, 70, 73, 78, 82, 89, 94. She decides to add 5 bonus points to every score. Which of the following correctly describes the effect on the mean and standard deviation of the scores?', NULL, $lyceon_json$[{"key":"A","text":"The mean increases by 5 and the standard deviation increases by 5"},{"key":"B","text":"The mean increases by 5 and the standard deviation stays the same"},{"key":"C","text":"The mean stays the same and the standard deviation increases by 5"},{"key":"D","text":"Both the mean and the standard deviation stay the same"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding a constant to every data point shifts the entire distribution, increasing the mean by that constant. However, the standard deviation does not change because every value shifts by the same amount, leaving the deviations from the new mean unchanged. Choosing the option where both increase by 5 reflects a misconception that additive shifts affect spread. Choosing the option where only the standard deviation changes reverses which statistic is affected by the shift. Choosing the option where neither changes ignores that the center of the distribution has moved.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23P0VU3', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $4(3x - 5) + 7x$?', NULL, $lyceon_json$[{"key":"A","text":"$19x - 20$"},{"key":"B","text":"$19x - 5$"},{"key":"C","text":"$12x - 20$"},{"key":"D","text":"$19x + 20$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $4(3x - 5) + 7x = 12x - 20 + 7x = 19x - 20$. The distractor $19x - 5$ results from failing to distribute the $4$ to the $-5$ term, leaving it as $-5$ instead of $-20$. The distractor $12x - 20$ omits the $7x$ term when combining like terms. The distractor $19x + 20$ applies a sign error when distributing, treating $4(-5)$ as $+20$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM247O0OU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $400$ voters in a city found that $58\\%$ support a new transit proposal, with a margin of error of $3\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all voters in the city support the proposal."},{"key":"B","text":"Between $55\\%$ and $61\\%$ of the sampled voters support the proposal."},{"key":"C","text":"It is plausible that between $55\\%$ and $61\\%$ of all voters in the city support the proposal."},{"key":"D","text":"At most $61\\%$ of all voters in the city support the proposal."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error creates a confidence interval around the sample statistic ($58\\% \\pm 3\\%$), meaning it is plausible that the true population proportion falls between $55\\%$ and $61\\%$. The statement that exactly $58\\%$ of all voters support the proposal treats the sample statistic as the exact population parameter, ignoring sampling variability. The statement about the sampled voters misapplies the interval — the margin of error addresses the population, not the sample (we already know the sample result exactly). The claim of at most $61\\%$ captures only the upper bound and ignores that the interval extends in both directions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24CMTR8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ students found that $74$ study French, $53$ study German, and $19$ study both French and German. If a student is selected at random from those who study French, what is the probability that the student also studies German?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{53}$"},{"key":"B","text":"$\\frac{19}{200}$"},{"key":"C","text":"$\\frac{19}{74}$"},{"key":"D","text":"$\\frac{53}{74}$"}]$lyceon_json$::jsonb, 'C', NULL, E'This is a conditional probability question: given the student studies French, what is the probability they also study German? The condition restricts the sample space to the $74$ French students. Of those, $19$ also study German, so the probability is $\\frac{19}{74}$. The distractor $\\frac{19}{53}$ incorrectly uses the number of German students as the denominator, confusing which language defines the condition. The distractor $\\frac{19}{200}$ uses the total number of students as the denominator, computing the unconditional probability of studying both rather than the conditional probability. The distractor $\\frac{53}{74}$ divides the total German count by the French count, which does not represent any meaningful conditional probability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24NUC12', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $5$ cm and a height of $18$ cm. What is the volume of the cylinder, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$90\\pi$"},{"key":"B","text":"$180\\pi$"},{"key":"C","text":"$450\\pi$"},{"key":"D","text":"$900\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(5)^2(18) = \\pi(25)(18) = 450\\pi$ cubic centimeters. The value $90\\pi$ results from forgetting to square the radius, computing $\\pi(5)(18) = 90\\pi$. The value $180\\pi$ comes from using the lateral surface area formula $2\\pi r h = 2\\pi(5)(18) = 180\\pi$ instead of the volume formula. The value $900\\pi$ is an arithmetic slip from doubling the correct volume.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24TXK7M', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which inequality represents all values of $x$ that satisfy $4x + 9 \\leq 37$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq 7$"},{"key":"B","text":"$x \\geq 7$"},{"key":"C","text":"$x \\leq 28$"},{"key":"D","text":"$x \\leq 11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 9 from both sides gives $4x \\leq 28$, and dividing both sides by 4 gives $x \\leq 7$. The distractor $x \\geq 7$ reverses the direction of the inequality sign. The distractor $x \\leq 28$ stops after subtracting 9 but omits dividing by 4. The distractor $x \\leq 11$ results from adding 9 to 37 instead of subtracting, yielding $46 / 4 = 11.5$, then rounding down.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26N8JEX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47^\\circ$ and the measure of angle $Q$ is $86^\\circ$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$41^\\circ$"},{"key":"B","text":"$47^\\circ$"},{"key":"C","text":"$133^\\circ$"},{"key":"D","text":"$227^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of any triangle is $180^\\circ$. Therefore, angle $R = 180^\\circ - 47^\\circ - 86^\\circ = 47^\\circ$. The value $41^\\circ$ results from a subtraction error such as computing $180 - 86 - 53$ instead of $180 - 86 - 47$. The value $133^\\circ$ comes from subtracting only one angle ($180 - 47 = 133$) without also subtracting the second angle, reflecting incomplete reasoning. The value $227^\\circ$ results from adding instead of subtracting ($47 + 86 + 94 = 227$), an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM273QC02', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'On a coordinate plane, which of the following points lies in the solution region of both $3x - 2y > 7$ and $x + 5y \\leq 18$?', NULL, $lyceon_json$[{"key":"A","text":"$(1, 4)$"},{"key":"B","text":"$(3, 1)$"},{"key":"C","text":"$(5, 1)$"},{"key":"D","text":"$(6, 3)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(5, 1)$: the first inequality gives $3(5) - 2(1) = 13 > 7$, which is true, and the second gives $5 + 5(1) = 10 \\leq 18$, which is also true. The point $(1, 4)$ fails the first inequality because $3(1) - 2(4) = -5$, which is not greater than 7; choosing it reflects testing only the second inequality. The point $(3, 1)$ gives $3(3) - 2(1) = 7$, which is not strictly greater than 7, so it fails the first inequality at the boundary; this error reflects treating $>$ as $\\geq$. The point $(6, 3)$ satisfies the first inequality ($18 - 6 = 12 > 7$) but fails the second ($6 + 15 = 21 > 18$); choosing it reflects checking only the first inequality.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27LJT80', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = -2(x + 4)^2 + 13$. Which of the following correctly describes the range of $f$?', NULL, $lyceon_json$[{"key":"A","text":"$f(x) \\leq 13$"},{"key":"B","text":"$f(x) \\geq 13$"},{"key":"C","text":"$f(x) \\leq -4$"},{"key":"D","text":"All real numbers"}]$lyceon_json$::jsonb, 'A', NULL, E'Since the coefficient of the squared term is $-2$ (negative), the parabola opens downward, so $f$ has a maximum at the vertex. The vertex is at $(-4, 13)$, so the maximum value is $13$ and the range is $f(x) \\leq 13$. The distractor $f(x) \\geq 13$ reverses the inequality, treating the parabola as opening upward. The distractor $f(x) \\leq -4$ confuses the $x$-coordinate of the vertex with a bound on the range. The distractor stating all real numbers ignores that quadratic functions have a bounded range on one side.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28W3D2F', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A delivery service charges a flat fee plus a fixed rate per package. When a business ships 13 packages, the total cost is $\\$89$. When it ships 29 packages, the total cost is $\\$153$. What is the total cost, in dollars, of shipping 41 packages?', NULL, $lyceon_json$[{"key":"A","text":"$\\$185$"},{"key":"B","text":"$\\$193$"},{"key":"C","text":"$\\$201$"},{"key":"D","text":"$\\$217$"}]$lyceon_json$::jsonb, 'C', NULL, E'The per-package rate is $\\frac{153 - 89}{29 - 13} = \\frac{64}{16} = 4$ dollars per package. The flat fee is $89 - 4(13) = 89 - 52 = 37$ dollars. For 41 packages the cost is $4(41) + 37 = 164 + 37 = 201$ dollars. The value $\\$185$ comes from partial reasoning, such as finding the rate but using an incorrect flat fee. The value $\\$193$ results from an arithmetic slip when computing $4 \\times 41$ or adding the flat fee. The value $\\$217$ arises from an equation setup error, for instance using a rate of $\\frac{64}{14}$ rounded to $\\$4.57$ per package and accumulating rounding error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28WUH3Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A standard deck of $52$ playing cards is shuffled. Two cards are drawn without replacement. Given that the first card drawn is a queen, what is the probability that the second card drawn is also a queen?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{4}{52}$"},{"key":"B","text":"$\\frac{3}{52}$"},{"key":"C","text":"$\\frac{3}{51}$"},{"key":"D","text":"$\\frac{4}{51}$"}]$lyceon_json$::jsonb, 'C', NULL, E'After the first queen is drawn, $3$ queens remain and the deck has $51$ cards left (since the draw is without replacement). The conditional probability is $\\frac{3}{51}$. The distractor $\\frac{4}{52}$ ignores the condition entirely and computes the unconditional probability of drawing a queen from a full deck, showing a gap in understanding conditional probability with dependent events. The distractor $\\frac{3}{52}$ correctly reduces the queen count to $3$ but fails to reduce the deck size from $52$ to $51$, applying the without-replacement rule only partially. The distractor $\\frac{4}{51}$ reduces the deck size to $51$ but forgets to reduce the queen count, making an arithmetic slip in tracking the remaining queens.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM297DO3J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $13$ units. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$13\\pi$"},{"key":"B","text":"$26\\pi$"},{"key":"C","text":"$52\\pi$"},{"key":"D","text":"$169\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = 2\\pi r = 2\\pi(13) = 26\\pi$. The value $13\\pi$ results from using $\\pi r$ instead of $2\\pi r$, omitting the factor of $2$. The value $52\\pi$ results from an arithmetic slip such as computing $4\\pi r$ instead of $2\\pi r$. The value $169\\pi$ comes from computing the area formula $\\pi r^2 = \\pi(13)^2 = 169\\pi$ instead of the circumference formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29AIBW2', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $3(2x - 7) + 11 = 5x + 2$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$4$"},{"key":"C","text":"$12$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distributing gives $6x - 21 + 11 = 5x + 2$, which simplifies to $6x - 10 = 5x + 2$. Subtracting $5x$ from both sides yields $x - 10 = 2$, so $x = 12$. The value $-6$ arises from a sign error when combining $-21 + 11$. The value 4 comes from stopping after distributing without correctly collecting all terms, a partial reasoning error. The value 18 results from an arithmetic slip when combining like terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29ELNOP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'After a 15% raise, an employee''s new monthly salary is \\$4,347. What was the employee''s monthly salary before the raise?', NULL, $lyceon_json$[{"key":"A","text":"\\$3,694.95"},{"key":"B","text":"\\$3,780"},{"key":"C","text":"\\$3,850"},{"key":"D","text":"\\$4,130"}]$lyceon_json$::jsonb, 'B', NULL, E'If the original salary is \\(x\\), then \\(1.15x = 4347\\), giving \\(x = \\frac{4347}{1.15} = 3780\\). The value \\$3,694.95 comes from subtracting 15% of the new salary (\\(4347 - 0.15 \\times 4347 = 3694.95\\)), which confuses working backward from a percentage increase with simply subtracting the percentage. The value \\$3,850 comes from an incorrect equation setup such as dividing by 1.13 or another wrong factor. The value \\$4,130 results from subtracting 5% instead of reversing a 15% increase, an arithmetic slip in identifying the percentage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29M3T8F', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $$\\frac{3x - 1}{5} + 2 = \\frac{x + 7}{2}\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{11}$"},{"key":"B","text":"$9$"},{"key":"C","text":"$17$"},{"key":"D","text":"$37$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying every term by 10 (the LCD of 5 and 2) gives $2(3x - 1) + 20 = 5(x + 7)$. Expanding: $6x - 2 + 20 = 5x + 35$, so $6x + 18 = 5x + 35$. Subtracting $5x$ and 18 from both sides yields $x = 17$. The value $\\frac{13}{11}$ results from an equation setup error such as cross-multiplying incorrectly without accounting for the added constant 2. The value 9 comes from partial reasoning, for instance forgetting to multiply the standalone 2 by the LCD. The value 37 arises from an arithmetic slip when combining $-2 + 20$ as $+22$ instead of $+18$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29MNZP3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the age (in years) and resting heart rate (in beats per minute) of 50 adults and fits a least-squares regression line: \\(\\hat{y} = -0.37x + 89.2\\), where \\(x\\) is age and \\(\\hat{y}\\) is predicted resting heart rate. The coefficient of determination is \\(r^2 = 0.46\\). One individual is 53 years old with a resting heart rate of 74 bpm. What is the residual for this individual, and what does \\(r^2 = 0.46\\) indicate?', NULL, $lyceon_json$[{"key":"A","text":"Residual is \\(4.41\\); 46% of the variation in heart rate is explained by age."},{"key":"B","text":"Residual is \\(-4.41\\); 46% of the variation in heart rate is explained by age."},{"key":"C","text":"Residual is \\(4.41\\); 46% of the variation in age is explained by heart rate."},{"key":"D","text":"Residual is \\(-4.41\\); 54% of the variation in heart rate is explained by age."}]$lyceon_json$::jsonb, 'A', NULL, E'Predicted value: \\(\\hat{y} = -0.37(53) + 89.2 = -19.61 + 89.2 = 69.59\\). Residual = observed minus predicted = \\(74 - 69.59 = 4.41\\). A positive residual means the actual heart rate exceeded the prediction. The coefficient \\(r^2 = 0.46\\) means 46% of the variation in the response variable (heart rate) is explained by the explanatory variable (age). The option with a residual of \\(-4.41\\) reverses the subtraction order, computing predicted minus observed instead. The option stating that variation in age is explained by heart rate swaps the roles of explanatory and response variables. The option citing 54% confuses \\(r^2\\) with the unexplained portion \\(1 - r^2\\).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29SV7U2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone is inscribed in a hemisphere such that the base of the cone coincides with the flat circular face of the hemisphere. The hemisphere has a radius of $6$ cm. What is the volume of the region inside the hemisphere but outside the cone, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$36\\pi$"},{"key":"B","text":"$72\\pi$"},{"key":"C","text":"$108\\pi$"},{"key":"D","text":"$144\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The hemisphere has radius $6$, so its volume is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(6)^3 = \\frac{2}{3}\\pi(216) = 144\\pi$. The inscribed cone shares the same circular base (radius $6$) and has its apex at the top of the hemisphere, so the cone''s height equals the hemisphere''s radius, $6$. The cone''s volume is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(36)(6) = 72\\pi$. The region inside the hemisphere but outside the cone has volume $144\\pi - 72\\pi = 72\\pi$. The value $36\\pi$ results from an arithmetic slip such as halving the cone volume instead of subtracting it from the hemisphere volume. The value $108\\pi$ comes from an equation setup error, such as using $\\frac{3}{4}\\pi r^3$ for the hemisphere volume or computing $144\\pi - 36\\pi$. The value $144\\pi$ is the hemisphere volume alone, without subtracting the cone.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B0LJ1C', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular patio has a length of $23$ feet and a width of $9$ feet. What is the area of the patio, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"$32$"},{"key":"B","text":"$64$"},{"key":"C","text":"$184$"},{"key":"D","text":"$207$"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $23 \\times 9 = 207$ square feet. The value $32$ comes from adding $23 + 9 = 32$, confusing perimeter components with area. The value $64$ is the perimeter $2(23 + 9) = 64$, using the wrong formula entirely. The value $184$ results from an arithmetic slip, computing $23 \\times 8$ instead of $23 \\times 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BNEJ6I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at \\$65 is on sale for 20% off. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"\\$45"},{"key":"B","text":"\\$52"},{"key":"C","text":"\\$55"},{"key":"D","text":"\\$58"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is \\(0.20 \\times 65 = \\$13\\). The sale price is \\(65 - 13 = \\$52\\). The value \\$45 results from a computational error, such as subtracting 20 from 65. The value \\$55 comes from subtracting only \\$10, as if the discount were about 15%. The value \\$58 results from miscalculating the percentage, for instance computing 10% as \\$6.50 and subtracting only that amount.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C9YJF4', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A florist can spend at most $\\$340$ on supplies for an event. Each centerpiece requires $\\$17$ in flowers, and a one-time delivery charge of $\\$51$ applies to the entire order. What is the maximum number of centerpieces the florist can prepare?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$17$"},{"key":"C","text":"$20$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'B', NULL, E'The inequality is $17c + 51 \\leq 340$. Subtracting 51 from both sides gives $17c \\leq 289$, and dividing by 17 gives $c \\leq 17$. The maximum number of centerpieces is 17. The distractor 16 results from a subtraction error such as computing $340 - 51 = 279$ and then $279 / 17 \\approx 16.4$, rounding down. The distractor 20 results from ignoring the delivery charge entirely and computing $340 / 17 = 20$. The distractor 23 results from subtracting the delivery charge on the wrong side, solving $17c \\leq 340 + 51 = 391$ and obtaining $391 / 17 = 23$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CSM6JF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = (x - 3)^2 + 7$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function $g(x) = (x - 3)^2 + 7$ is in vertex form. Since $(x - 3)^2 \\geq 0$ for all real $x$, the minimum occurs when $(x - 3)^2 = 0$, giving $g(3) = 0 + 7 = 7$. The distractor $3$ confuses the $x$-coordinate of the vertex with the minimum output value of the function. The distractor $-7$ applies a sign error to the vertical shift. The distractor $-3$ misreads the horizontal shift as the minimum output value and negates it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E9874V', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $PQR$ with the right angle at $R$, $\\sin(P) = \\frac{7}{25}$. If the perimeter of triangle $PQR$ is $112$, what is the length of side $QR$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$28$"},{"key":"C","text":"$48$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $\\sin(P) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{QR}{PQ} = \\frac{7}{25}$, let $QR = 7k$ and $PQ = 25k$. By the Pythagorean theorem, $PR = \\sqrt{(25k)^2 - (7k)^2} = \\sqrt{625k^2 - 49k^2} = 24k$. The perimeter is $7k + 24k + 25k = 56k = 112$, so $k = 2$ and $QR = 7 \\times 2 = 14$. The value $28$ is an arithmetic slip from doubling $QR$ or miscalculating the scale factor. The value $48$ is the length of side $PR = 24k = 48$, reflecting partial reasoning that finds a different side than the one asked for. The value $50$ is the hypotenuse $PQ = 25k = 50$, a misread of which side the question requests.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EM9EOM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $RST$ with the right angle at $T$, $\\sin(R) = \\frac{7}{25}$. What is $\\cos(R)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{24}$"},{"key":"B","text":"$\\frac{18}{25}$"},{"key":"C","text":"$\\frac{24}{25}$"},{"key":"D","text":"$\\frac{7}{25}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin(R) = \\frac{7}{25}$, the side opposite angle $R$ is $7$ and the hypotenuse is $25$. By the Pythagorean theorem, the adjacent side is $\\sqrt{25^2 - 7^2} = \\sqrt{625 - 49} = \\sqrt{576} = 24$. Therefore $\\cos(R) = \\frac{24}{25}$. The value $\\frac{7}{24}$ results from computing $\\tan(R)$ instead of $\\cos(R)$, a concept gap about trigonometric ratios. The value $\\frac{18}{25}$ comes from subtracting $25 - 7 = 18$ instead of using the Pythagorean theorem, an arithmetic approach error. The value $\\frac{7}{25}$ simply repeats the given sine value, misreading the question.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ERFME3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for 7 cups of broth to make 42 servings of soup. How many cups of broth are needed to make 18 servings of soup?', NULL, $lyceon_json$[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"6"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of broth to servings is \\(\\frac{7}{42} = \\frac{1}{6}\\) cup per serving. For 18 servings: \\(18 \\times \\frac{1}{6} = 3\\) cups. The value 2 results from an arithmetic error when simplifying the proportion. The value 4 comes from setting up the proportion incorrectly, for example computing \\(\\frac{7 \\times 18}{42}\\) with a multiplication slip. The value 6 comes from confusing the unit rate denominator with the answer, using the 6 from \\(\\frac{1}{6}\\) directly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F1LJZE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{3x^2 + 17x - 28}{x + 7} = ax + b$ for all $x \\neq -7$, what is the value of $a - b$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring the numerator: $3x^2 + 17x - 28 = (x + 7)(3x - 4)$, verified by expanding $(x + 7)(3x - 4) = 3x^2 - 4x + 21x - 28 = 3x^2 + 17x - 28$. So $\\frac{3x^2 + 17x - 28}{x + 7} = 3x - 4$, giving $a = 3$ and $b = -4$. Therefore $a - b = 3 - (-4) = 7$. The distractor $-1$ results from computing $a + b = 3 + (-4) = -1$ instead of $a - b$. The distractor $-7$ comes from a sign error, computing $b - a = -4 - 3 = -7$. The distractor $1$ arises from an arithmetic slip such as misidentifying $b$ as $-2$ and computing $3 - (-2) = 5$, or from other factor-pair errors during the division.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F4VHCO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up its goods by 40% over wholesale cost and then offers a seasonal discount of 25% off the marked-up price. If a customer pays \\$73.50 for an item after the discount, what was the wholesale cost?', NULL, $lyceon_json$[{"key":"A","text":"\\$52.50"},{"key":"B","text":"\\$56.25"},{"key":"C","text":"\\$70"},{"key":"D","text":"\\$98"}]$lyceon_json$::jsonb, 'C', NULL, E'Let the wholesale cost be \\(w\\). The marked-up price is \\(1.4w\\), and after a 25% discount the customer pays \\(0.75 \\times 1.4w = 1.05w\\). Setting \\(1.05w = 73.50\\) gives \\(w = 70\\). The value \\$52.50 results from treating the net effect as a 30% increase (adding 40% and subtracting 25% from 73.50 incorrectly). The value \\$56.25 comes from dividing by an incorrect combined factor such as \\(73.50 / 1.30\\). The value \\$98 comes from dividing \\$73.50 by 0.75 alone, reversing only the discount while ignoring that the markup must also be reversed.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FJFCKI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours spent practicing piano each week and a student''s score on a performance exam. The line of best fit has a slope of 4.3. Which of the following is the best interpretation of this slope?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of practice per week, the exam score is predicted to increase by 4.3 points."},{"key":"B","text":"For each additional point on the exam, the student practices 4.3 more hours per week."},{"key":"C","text":"A student who practices 4.3 hours per week is predicted to score 100 on the exam."},{"key":"D","text":"The exam score is 4.3 times the number of practice hours."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a line of best fit represents the predicted change in the dependent variable (exam score) for each one-unit increase in the independent variable (hours of practice). A slope of 4.3 means each additional hour of practice predicts a 4.3-point increase in score. The option reversing the variables confuses the roles of independent and dependent variables. The option about scoring 100 conflates the slope with a specific prediction at a particular input value. The option describing a pure multiplicative relationship misinterprets slope as a proportionality constant, ignoring the y-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JLWLC6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{4x^2 - 25}{2x + 5}$ for $x \\neq -\\frac{5}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5$"},{"key":"B","text":"$2x - 5$"},{"key":"C","text":"$4x - 5$"},{"key":"D","text":"$2x^2 - 5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $4x^2 - 25$ is a difference of squares: $(2x)^2 - 5^2 = (2x + 5)(2x - 5)$. Dividing by $(2x + 5)$ yields $2x - 5$. The distractor $2x + 5$ results from canceling the denominator but keeping the wrong factor. The distractor $4x - 5$ comes from incorrectly factoring the numerator without recognizing the squared terms. The distractor $2x^2 - 5$ results from dividing each term of the numerator by $2$ instead of by the binomial $(2x + 5)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KDSXP0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization selects a random sample of $600$ adults in a state and finds that $47\\%$ favor Candidate A and $53\\%$ favor Candidate B, with a margin of error of $4\\%$ for each estimate. A reporter claims that Candidate B is clearly ahead in the state. Which of the following best evaluates the reporter''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is justified because $53\\%$ is greater than $47\\%$."},{"key":"B","text":"The claim is not justified because the confidence intervals for the two candidates overlap."},{"key":"C","text":"The claim is justified because the sample size of $600$ is large enough to eliminate sampling error."},{"key":"D","text":"The claim is not justified because the poll did not survey every adult in the state."}]$lyceon_json$::jsonb, 'B', NULL, E'Candidate A''s confidence interval is $43\\%$ to $51\\%$, and Candidate B''s is $49\\%$ to $57\\%$. Because these intervals overlap (both include values near $49\\%$–$51\\%$), the difference between the candidates is within the margin of error, so the data do not clearly establish that one candidate leads. The claim based solely on $53\\% > 47\\%$ uses partial reasoning — it ignores that the observed difference ($6$ percentage points) does not exceed the combined uncertainty. The assertion that $600$ respondents eliminate sampling error reflects a conceptual gap: no finite sample eliminates sampling error entirely. The objection that the poll did not survey every adult describes a feature of all sample-based polls and does not by itself invalidate a poll''s conclusions — the relevant issue is whether the margin of error accounts for the observed difference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KELRUK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $DEF$, the exterior angle at vertex $F$ measures $149^\\circ$. If angle $D$ measures $71^\\circ$, what is the measure, in degrees, of angle $E$?', NULL, $lyceon_json$[{"key":"A","text":"$31^\\circ$"},{"key":"B","text":"$78^\\circ$"},{"key":"C","text":"$109^\\circ$"},{"key":"D","text":"$149^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the exterior angle theorem, the exterior angle at a vertex of a triangle equals the sum of the two non-adjacent interior angles. Therefore $149^\\circ = 71^\\circ + \\text{angle } E$, which gives angle $E = 149^\\circ - 71^\\circ = 78^\\circ$. The value $31^\\circ$ results from computing $180 - 149 = 31$, treating the exterior angle as an interior angle rather than applying the exterior angle theorem. The value $109^\\circ$ comes from computing $180 - 71 = 109$, which gives the supplement of angle $D$ rather than using the exterior angle relationship. The value $149^\\circ$ simply restates the given exterior angle without performing any calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LGGE7E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A machine fills 130 bottles in 5 minutes. At this rate, how many minutes will it take the machine to fill 897 bottles?', NULL, $lyceon_json$[{"key":"A","text":"31.5"},{"key":"B","text":"34.5"},{"key":"C","text":"38.4"},{"key":"D","text":"44.85"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is \\(\\frac{130}{5} = 26\\) bottles per minute. Time for 897 bottles: \\(\\frac{897}{26} = 34.5\\) minutes. The value 31.5 arises from a computational slip when dividing. The value 38.4 results from incorrectly computing the rate as \\(\\frac{130}{5.56}\\) or another setup error. The value 44.85 comes from computing \\(\\frac{897}{5} \\times \\frac{1}{4}\\), confusing the relationship between rate and time.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LQYT79', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line is perpendicular to the line $5x - 3y = 11$ and passes through the point $(4, -1)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{5}$"},{"key":"B","text":"$-\\frac{7}{5}$"},{"key":"C","text":"$\\frac{17}{5}$"},{"key":"D","text":"$\\frac{7}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $5x - 3y = 11$ in slope-intercept form gives $y = \\frac{5}{3}x - \\frac{11}{3}$, so the slope is $\\frac{5}{3}$. A perpendicular line has slope $-\\frac{3}{5}$. Using point-slope form: $y - (-1) = -\\frac{3}{5}(x - 4)$, so $y + 1 = -\\frac{3}{5}x + \\frac{12}{5}$. Thus $y = -\\frac{3}{5}x + \\frac{12}{5} - 1 = -\\frac{3}{5}x + \\frac{7}{5}$. The $y$-intercept is $\\frac{7}{5}$. The value $-\\frac{7}{5}$ comes from a sign error when subtracting 1 from $\\frac{12}{5}$. The value $\\frac{17}{5}$ results from an arithmetic slip of adding 1 instead of subtracting. The value $\\frac{7}{3}$ reflects a concept gap—using the reciprocal slope $\\frac{3}{5}$ instead of the negative reciprocal.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LVHEBK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $250$ households in a county and finds that the mean monthly electricity bill is $\\$137$ with a margin of error of $\\$11$. Another researcher surveys a random sample of $1{,}000$ households from the same county and finds a mean monthly electricity bill of $\\$141$ with a margin of error of $\\$5$. Which of the following best explains why the second survey has a smaller margin of error?', NULL, $lyceon_json$[{"key":"A","text":"The second survey found a higher mean, which always reduces the margin of error."},{"key":"B","text":"The second survey used a larger sample size, which decreases the margin of error."},{"key":"C","text":"The second survey was conducted more recently, so the data are more accurate."},{"key":"D","text":"The second survey had a smaller range of values in its data set."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely related to the square root of the sample size: larger samples produce smaller margins of error, all else being equal. The second survey sampled $1{,}000$ households versus $250$, which is why its margin of error ($\\$5$) is smaller than the first survey''s ($\\$11$). The claim that a higher mean reduces the margin of error conflates the value of the statistic with sampling precision — the mean''s magnitude does not determine margin of error. The suggestion about recency introduces an irrelevant factor; timing does not systematically change margin of error. The claim about a smaller range of values describes variability, which can affect margin of error, but the question provides no evidence about the spread of each sample — the key observable difference is sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LVHEO3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $7x - 19 = 30$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding 19 to both sides gives $7x = 49$, and dividing both sides by 7 yields $x = 7$. The value 5 results from dividing 30 by 7 and rounding incorrectly, an arithmetic slip. The value 8 comes from subtracting 19 instead of adding it before dividing, a sign error. The value 11 results from adding 49 and dividing by a wrong factor, an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MIEAGW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $JKL$, the exterior angle at vertex $L$ measures $138^\\circ$. If the measure of angle $J$ is twice the measure of angle $K$, what is the measure, in degrees, of angle $J$?', NULL, $lyceon_json$[{"key":"A","text":"$46^\\circ$"},{"key":"B","text":"$69^\\circ$"},{"key":"C","text":"$84^\\circ$"},{"key":"D","text":"$92^\\circ$"}]$lyceon_json$::jsonb, 'D', NULL, E'By the exterior angle theorem, the exterior angle at $L$ equals the sum of the two non-adjacent interior angles: angle $J$ + angle $K = 138^\\circ$. Since angle $J = 2 \\times$ angle $K$, substituting gives $2K + K = 138$, so $3K = 138$ and $K = 46^\\circ$. Therefore angle $J = 2 \\times 46 = 92^\\circ$. The value $46^\\circ$ is the measure of angle $K$, not angle $J$, a misread of what the question asks. The value $69^\\circ$ comes from dividing $138$ by $2$ without accounting for the $2:1$ ratio. The value $84^\\circ$ results from incorrectly using the interior angle at $L$ as $180 - 138 = 42$ and then doubling it, confusing which angle is the base of the ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PGSKF1', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 3x + 11$, what is the value of $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$31$"},{"key":"C","text":"$32$"},{"key":"D","text":"$42$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 7$ gives $f(7) = 3(7) + 11 = 21 + 11 = 32$. The value 21 results from computing only $3 \\times 7$ and neglecting to add the constant, a partial reasoning error. The value 31 comes from an arithmetic slip such as computing $21 + 10$ instead of $21 + 11$. The value 42 arises from an equation setup error, such as computing $3 \\times (7 + 7)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QIYZPH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $7$ and the hypotenuse has length $25$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$22$"},{"key":"C","text":"$24$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the Pythagorean theorem, $a^2 + 7^2 = 25^2$, so $a^2 = 625 - 49 = 576$, and $a = \\sqrt{576} = 24$. The value $18$ results from subtracting $25 - 7 = 18$ instead of using the Pythagorean theorem, an equation setup error. The value $22$ comes from an arithmetic slip in computing $625 - 49$ incorrectly. The value $32$ results from adding $25 + 7 = 32$, reflecting a concept gap about how the Pythagorean theorem relates the sides.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R30FXX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A printer uses ink at a rate of 0.03 milliliters per page. Ink cartridges hold 17 milliliters each and cost \\$23.50 per cartridge. Cartridges cannot be purchased in fractional quantities. If a company needs to print 8,700 pages, what is the minimum total cost for the ink cartridges needed?', NULL, $lyceon_json$[{"key":"A","text":"\\$352.50"},{"key":"B","text":"\\$361.06"},{"key":"C","text":"\\$376.00"},{"key":"D","text":"\\$399.50"}]$lyceon_json$::jsonb, 'C', NULL, E'Total ink needed: \\(8700 \\times 0.03 = 261\\) mL. Number of cartridges: \\(\\frac{261}{17} = 15.35\\), which must be rounded up to 16 since partial cartridges cannot be purchased. Cost: \\(16 \\times 23.50 = \\$376.00\\). The value \\$352.50 results from rounding 15.35 down to 15 cartridges, which would leave the company short on ink. The value \\$361.06 results from computing the cost as if fractional cartridges could be bought (\\(15.35 \\times 23.50 \\approx 360.73\\)) with an additional rounding error. The value \\$399.50 comes from using 17 cartridges, confusing the cartridge capacity value of 17 mL with the number of cartridges needed.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RJUB0S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers want to determine whether a new fertilizer increases tomato yield. They randomly select $80$ plots from a large agricultural region and randomly assign $40$ plots to receive the new fertilizer and $40$ plots to receive the standard fertilizer. At harvest, the mean yield of plots using the new fertilizer is significantly higher. A farm magazine reports: \\"The new fertilizer has been proven to increase tomato yield for all farmers.\\" Which of the following best evaluates the magazine''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the study used random assignment."},{"key":"B","text":"The claim is supported because the result was statistically significant."},{"key":"C","text":"The claim overgeneralizes because the plots were from a single region, so results may not apply to all farmers everywhere."},{"key":"D","text":"The claim is invalid because the study should have been a survey rather than an experiment."}]$lyceon_json$::jsonb, 'C', NULL, E'Although random assignment supports a causal conclusion within the study, the plots were selected from a single agricultural region. The results cannot be generalized to all farmers everywhere because soil, climate, and growing conditions vary across regions. The magazine''s use of \\"all farmers\\" overgeneralizes beyond the study''s scope. Claiming the study is supported solely because of random assignment or statistical significance ignores the limitation on generalizability. Suggesting a survey instead of an experiment reflects a fundamental misunderstanding — surveys measure opinions or characteristics, while experiments are needed to test causal effects of treatments.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SH2CHG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher finds that employees who participate in a company wellness program have fewer sick days per year than employees who do not participate. The wellness program is voluntary. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The wellness program causes employees to have fewer sick days."},{"key":"B","text":"There is an association between participating in the wellness program and having fewer sick days."},{"key":"C","text":"Employees who do not participate in the program should be required to join."},{"key":"D","text":"The study proves that exercise reduces illness."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participation is voluntary, this is an observational study — participants self-selected into the program. Self-selection introduces potential confounding variables (e.g., health-conscious employees may be more likely both to join and to have fewer sick days). The study can establish an association but not causation. The causal claim that the program causes fewer sick days is unwarranted without random assignment to eliminate confounders. The recommendation to require employees to join is a policy prescription not supported by observational data alone. The claim that the study proves exercise reduces illness overgeneralizes beyond the study''s scope and treats an association as proof of a causal mechanism.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SXMZ2E', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A system of two linear equations has no solution. One of the equations is $7x - 4y = 11$. Which of the following could be the other equation?', NULL, $lyceon_json$[{"key":"A","text":"$14x - 8y = 15$"},{"key":"B","text":"$14x - 8y = 22$"},{"key":"C","text":"$7x + 4y = 11$"},{"key":"D","text":"$4x - 7y = 11$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system has no solution when the lines are parallel: same slope but different $y$-intercepts. Rewriting $7x - 4y = 11$ gives slope $\\frac{7}{4}$. The equation $14x - 8y = 15$ simplifies to $7x - 4y = 7.5$, which has the same slope $\\frac{7}{4}$ but a different constant, so the lines are parallel and the system has no solution. The equation $14x - 8y = 22$ simplifies to $7x - 4y = 11$, which is the same line, yielding infinitely many solutions rather than none; selecting it reflects confusing no solution with dependent equations. The equation $7x + 4y = 11$ has slope $-\\frac{7}{4}$, which differs from $\\frac{7}{4}$, so the lines intersect in exactly one solution; this error reflects changing the sign of the $y$-coefficient without recognizing that it changes the slope. The equation $4x - 7y = 11$ has slope $\\frac{4}{7}$, which also differs from $\\frac{7}{4}$, producing one solution; this error reflects swapping the coefficients of $x$ and $y$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TO4ZVP', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the system of equations below?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TSUYZ0', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-intercept of the line $4x + 7y = 28$?', NULL, $lyceon_json$[{"key":"A","text":"$(4, 0)$"},{"key":"B","text":"$(7, 0)$"},{"key":"C","text":"$(0, 4)$"},{"key":"D","text":"$(0, 7)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $x$-intercept occurs where $y = 0$. Substituting into $4x + 7(0) = 28$ gives $4x = 28$, so $x = 7$, and the intercept is $(7, 0)$. The point $(4, 0)$ confuses the coefficient of $x$ with the intercept value, a concept gap. The points $(0, 4)$ and $(0, 7)$ are $y$-intercept candidates rather than $x$-intercepts, indicating the question was misread.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TXO0XU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages of 5 members of a club are 19, 23, 27, 23, and 31. What is the mean age of the members?', NULL, $lyceon_json$[{"key":"A","text":"23"},{"key":"B","text":"24.6"},{"key":"C","text":"25"},{"key":"D","text":"27"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of ages is \\(19 + 23 + 27 + 23 + 31 = 123\\). The mean is \\(\\frac{123}{5} = 24.6\\). The value 23 is the median and mode, not the mean, reflecting a confusion between different measures of center. The value 25 results from an addition error when summing the ages. The value 27 results from picking the middle value of the list as given rather than computing the arithmetic average.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U1QZH0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $5$ red candies, $6$ blue candies, and $9$ yellow candies. If one candy is selected at random, what is the probability that it is yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{20}$"},{"key":"B","text":"$\\frac{9}{11}$"},{"key":"C","text":"$\\frac{6}{20}$"},{"key":"D","text":"$\\frac{1}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of candies is $5 + 6 + 9 = 20$. The probability of selecting a yellow candy is $\\frac{9}{20}$. The distractor $\\frac{9}{11}$ divides by the number of non-yellow candies ($5 + 6 = 11$) instead of the total, reflecting an equation setup error. The distractor $\\frac{6}{20}$ uses the count of blue candies rather than yellow, misreading the question. The distractor $\\frac{1}{3}$ incorrectly assumes each of the three colors is equally likely, ignoring that the colors have different counts.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U52EUX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university randomly assigns $120$ students to two groups. One group receives a new study-skills workshop, and the other group receives no workshop. At the end of the semester, students who attended the workshop had a higher mean GPA than the control group. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The workshop is likely to improve GPA for all college students nationwide."},{"key":"B","text":"Students who attend study-skills workshops are naturally more motivated than those who do not."},{"key":"C","text":"The workshop likely caused the higher mean GPA among the students in this experiment."},{"key":"D","text":"There is an association between attending the workshop and GPA, but causation cannot be established."}]$lyceon_json$::jsonb, 'C', NULL, E'Because students were randomly assigned to the workshop or control group, this is a randomized experiment. Random assignment controls for confounding variables (such as motivation), so a causal conclusion about the treatment effect is appropriate for the participants studied. The claim about all college students nationwide is an overgeneralization — the result applies to the population from which the sample was drawn, not all students everywhere. The claim about natural motivation contradicts the study design: random assignment ensures that pre-existing differences like motivation are balanced across groups, so the groups are not self-selected. The claim that causation cannot be established applies to observational studies, not randomized experiments — it reflects partial understanding of when causal inference is valid.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UIPF0Q', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations below has two solutions. What is the value of $y$ for the solution where $x > 0$?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UZ9M4N', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $2x^2 + 7x + 11 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = 7^2 - 4(2)(11) = 49 - 88 = -39$. Since the discriminant is negative, the equation has no real solutions. The distractor $1$ reflects the misconception that a negative discriminant yields exactly one solution, confusing it with a zero discriminant. The distractor $2$ assumes all quadratic equations have two real solutions without checking the discriminant. The distractor $4$ misapplies the degree of the equation, perhaps confusing a quadratic with a quartic.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W32UOG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 14x + 6y + 42 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$\\sqrt{42}$"},{"key":"C","text":"$8$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'A', NULL, E'Completing the square: $(x^2 - 14x + 49) + (y^2 + 6y + 9) = -42 + 49 + 9$, which gives $(x - 7)^2 + (y + 3)^2 = 16$. The radius is $r = \\sqrt{16} = 4$. The value $\\sqrt{42}$ comes from incorrectly treating the constant term $42$ as $r^2$, misreading the equation. The value $8$ is an arithmetic slip, perhaps from doubling the radius or miscomputing the completed square. The value $16$ gives $r^2$ rather than $r$, a concept gap about extracting the radius from standard form.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W5QAX4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle has center $(2, -5)$ and passes through the point $(11, 7)$. A chord of this circle has its midpoint at $(2, 7)$. What is the length of this chord?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$12$"},{"key":"C","text":"$15$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'D', NULL, E'The radius equals the distance from the center $(2, -5)$ to $(11, 7)$: $r = \\sqrt{(11-2)^2 + (7-(-5))^2} = \\sqrt{81 + 144} = \\sqrt{225} = 15$. The distance from the center $(2, -5)$ to the chord''s midpoint $(2, 7)$ is $|7 - (-5)| = 12$. A line from the center to the midpoint of a chord is perpendicular to the chord, forming a right triangle where the radius is the hypotenuse, the center-to-midpoint distance is one leg, and half the chord length is the other leg. So half the chord $= \\sqrt{15^2 - 12^2} = \\sqrt{225 - 144} = \\sqrt{81} = 9$, and the full chord length is $2 \\times 9 = 18$. The value $9$ is only half the chord, reflecting partial reasoning. The value $12$ is the center-to-midpoint distance, not the chord length, a concept gap. The value $15$ is the radius, not the chord length.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X7V8MF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The equation \\(y = 2.7x + 14.9\\) models the relationship between the number of weeks since a plant was transplanted, \\(x\\), and the height of the plant in centimeters, \\(y\\). According to the model, what is the predicted height, in centimeters, of the plant 11 weeks after transplanting?', NULL, $lyceon_json$[{"key":"A","text":"29.7"},{"key":"B","text":"39.8"},{"key":"C","text":"44.6"},{"key":"D","text":"47.1"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting \\(x = 11\\): \\(y = 2.7(11) + 14.9 = 29.7 + 14.9 = 44.6\\). The value 29.7 comes from computing only the product \\(2.7 \\times 11\\) without adding the y-intercept, stopping partway through the calculation. The value 39.8 results from a multiplication error such as computing \\(2.7 \\times 11\\) as 24.9 instead of 29.7. The value 47.1 results from an addition slip after correctly computing the product 29.7, perhaps adding 17.4 instead of 14.9.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y9OZ6V', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $g$ satisfies $g(2) = 17$ and $g(6) = 41$. What is the rate of change of $g$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$8$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate of change is $\\frac{g(6) - g(2)}{6 - 2} = \\frac{41 - 17}{4} = \\frac{24}{4} = 6$. The value 4 comes from using the difference in $x$-values alone, misreading what the question asks. The value 8 results from an equation setup error such as dividing the difference in outputs by 3 instead of 4. The value 12 arises from an arithmetic slip, for instance computing $41 - 17 = 24$ and then halving instead of dividing by 4.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YBIYVO', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, 9)$ and $(5, 3)$. Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = -2x + 13$"},{"key":"B","text":"$y = 2x + 5$"},{"key":"C","text":"$y = -2x + 5$"},{"key":"D","text":"$y = 2x + 13$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{3 - 9}{5 - 2} = \\frac{-6}{3} = -2$. Using point-slope form with $(2, 9)$: $y - 9 = -2(x - 2)$, which gives $y = -2x + 4 + 9 = -2x + 13$. The equation $y = 2x + 5$ results from a sign error in computing the slope as positive 2 and then finding the wrong intercept. The equation $y = -2x + 5$ has the correct slope but an arithmetic slip in calculating the $y$-intercept. The equation $y = 2x + 13$ uses an incorrect positive slope due to a sign error in the slope formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZZRNQW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set has 9 values listed in increasing order: 4, 7, 11, 13, 17, 19, 22, 26, 33. If the value 33 is replaced by 58, which of the following statistics changes?', NULL, $lyceon_json$[{"key":"A","text":"Median only"},{"key":"B","text":"Mean only"},{"key":"C","text":"Both the mean and the median"},{"key":"D","text":"Neither the mean nor the median"}]$lyceon_json$::jsonb, 'B', NULL, E'The median of 9 ordered values is the 5th value, which is 17 in both the original and modified sets since only the last value changed. The mean changes because the sum increases by \\(58 - 33 = 25\\), raising the average. Therefore only the mean changes. Choosing the median-only option reflects confusion about which measure is sensitive to extreme values. Choosing both reflects incorrectly believing the median shifts when a non-central value changes. Choosing neither ignores the effect of the increased sum on the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW214OY4B', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead conservator nor the two assistants who worked on restoring the seventeenth-century altarpiece _____ able to determine whether the underlying sketch had been drawn by the same artist who completed the final oil layers.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"has been"}]$lyceon_json$::jsonb, 'C', NULL, E'When a "neither...nor" construction joins a singular subject and a plural subject, the verb agrees with the subject closest to it. Here, "nor" is followed by "the two assistants," which is plural, so the verb must be plural as well. Additionally, the rest of the sentence uses past tense ("had been drawn," "completed"), so the past-tense plural "were" is correct. The singular past-tense "was" incorrectly agrees with the more distant subject "lead conservator" rather than the nearer "two assistants." The singular present-tense "is" fails on both number agreement and tense consistency. The singular present-perfect "has been" also fails on number agreement and introduces a tense inconsistent with the past-tense narrative.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2191EH8', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The muralist Kwame Acheampong, who had been commissioned by the city of Rotterdam to transform a derelict warehouse into a community art _____ unveiled the finished installation at a public ceremony attended by over nine hundred residents.', $lyceon_json$[{"key":"A","text":"space"},{"key":"B","text":"space;"},{"key":"C","text":"space:"},{"key":"D","text":"space,"}]$lyceon_json$::jsonb, 'D', NULL, E'The clause "who had been commissioned by the city of Rotterdam to transform a derelict warehouse into a community art space" is a nonrestrictive relative clause modifying "Kwame Acheampong." Because this clause is opened by a comma before "who," it must be closed with a matching comma after "space" to properly set off the parenthetical information before the main verb "unveiled." Omitting the comma after "space" fails to close the nonrestrictive clause, fusing it into the main predicate and creating ambiguity. A semicolon after "space" would incorrectly signal the boundary between two independent clauses, but "unveiled" is the main verb of the sentence and does not begin a new clause. A colon after "space" would incorrectly introduce a list or explanation where none follows.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
