INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24J484T', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Tobias Lindgren has spent seven summers cataloging jellyfish populations along the Norwegian coastline _____ his data now form the basis of a national monitoring program tracking shifts in Arctic marine biodiversity.', $lyceon_json$[{"key":"A","text":"coastline, his"},{"key":"B","text":"coastline his"},{"key":"C","text":"coastline. His"},{"key":"D","text":"coastline, and, his"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank falls between two independent clauses: "Marine biologist Tobias Lindgren has spent seven summers cataloging jellyfish populations along the Norwegian coastline" and "his data now form the basis of a national monitoring program tracking shifts in Arctic marine biodiversity." A period correctly separates these independent clauses into two sentences. Using a comma alone ("coastline, his") creates a comma splice, which is not standard. Omitting all punctuation ("coastline his") produces a fused sentence. Adding "and" with an unnecessary comma after it ("coastline, and, his") incorrectly separates the conjunction from the clause it introduces.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
