INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26MOTP0', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the passage ("This genomic . . . acoustic camouflage")?', E'Certain species of moths have evolved wing scales that absorb ultrasonic frequencies used by echolocating bats, effectively rendering the moths invisible to their primary predators. Acoustic ecologist Tomoko Kuroda demonstrated in 2021 that these absorptive scales share structural similarities with sound-dampening metamaterials engineered for industrial noise reduction. This genomic convergence between biological evolution and human engineering, Kuroda argues, suggests that the physical constraints governing acoustic camouflage are narrow enough to drive vastly different systems toward nearly identical solutions.', $lyceon_json$[{"key":"A","text":"It provides a specific example that contradicts the claim made in the first sentence"},{"key":"B","text":"It presents a broader theoretical implication drawn from the similarity described in the preceding sentence"},{"key":"C","text":"It qualifies the findings of Kuroda's 2021 study by identifying a significant limitation"},{"key":"D","text":"It summarizes the experimental methodology that Kuroda used to study moth wing scales"}]$lyceon_json$::jsonb, 'B', NULL, E'The third sentence takes the structural similarity identified in the second sentence (moth scales and engineered metamaterials) and draws a broader conclusion: that the physical constraints on acoustic camouflage are so narrow that different systems converge on the same solution. This functions as a theoretical implication built on the preceding observation. Contradicting the first sentence misreads the passage — the third sentence extends, not opposes, the claim about moths absorbing ultrasonic frequencies. Identifying a significant limitation is not what occurs; the sentence expands the significance of the finding rather than restricting it. Summarizing experimental methodology is inaccurate because the sentence discusses a theoretical interpretation, not the procedures Kuroda employed.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW279LY4Z', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'In 1987, geochemist Yuri Kolesnikov collected sediment cores from the floor of Lake Baikal in Siberia and discovered unusually high concentrations of iridium in a stratum dating to approximately 770,000 years ago. Kolesnikov proposed that the iridium originated from a meteorite impact, a hypothesis that prompted several subsequent expeditions to the lake between 1991 and 2003.', $lyceon_json$[{"key":"A","text":"To describe a scientific finding and its effect on further research"},{"key":"B","text":"To evaluate the accuracy of a geochemist's controversial claim"},{"key":"C","text":"To compare two methods for analyzing sediment composition"},{"key":"D","text":"To explain the geological processes that formed Lake Baikal"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Kolesnikov''s discovery of high iridium concentrations, states his hypothesis, and notes that the finding prompted subsequent expeditions. Its function is to describe a scientific finding and its effect on further research. Evaluating the accuracy of a controversial claim misidentifies the passage''s purpose — the passage reports the hypothesis and its consequences but does not assess whether Kolesnikov was right or wrong. Comparing two methods of sediment analysis is not addressed anywhere in the passage; only one method is mentioned. Explaining the geological formation of Lake Baikal goes beyond the passage''s content, which concerns a specific geochemical discovery, not the lake''s geological origins.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27DONHS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Architect Seonaid Macrae designed a public library in Dundee that uses recycled shipping containers as structural modules _____ the unconventional materials reduced construction costs by nearly forty percent compared to traditional steel framing.', $lyceon_json$[{"key":"A","text":"modules, the"},{"key":"B","text":"modules; the"},{"key":"C","text":"modules the"},{"key":"D","text":"modules, the,"}]$lyceon_json$::jsonb, 'B', NULL, E'Two independent clauses appear on either side of the blank: one ending with "modules" and the next beginning with "the unconventional materials reduced." A semicolon correctly joins two closely related independent clauses without a coordinating conjunction. A comma alone ("modules, the") produces a comma splice because no coordinating conjunction follows. Omitting punctuation entirely ("modules the") creates a fused sentence. Adding a comma after "the" as well ("modules, the,") creates a comma splice and also incorrectly sets off "the" as a parenthetical element.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A2WPST', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every spring, the network of hiking trails that winds through the Appalachian foothills near Brevard, North Carolina, _____ hundreds of amateur botanists searching for rare wildflower species.', $lyceon_json$[{"key":"A","text":"attract"},{"key":"B","text":"attracts"},{"key":"C","text":"have attracted"},{"key":"D","text":"are attracting"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "network," which is singular. The intervening prepositional phrase "of hiking trails that winds through the Appalachian foothills near Brevard, North Carolina" does not change the number of the subject. The singular verb "attracts" correctly agrees with "network." The plural verb "attract" incorrectly agrees with the nearer noun "trails" rather than the actual subject. The plural verb phrase "have attracted" fails to agree with the singular subject. The plural progressive form "are attracting" also fails in number agreement with the singular "network."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B73XKR', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A team of marine biologists studying the deep-water coral reefs off the coast of Mauritania published findings in 2023 indicating that these reefs, located at depths exceeding 450 meters, harbor at least seventeen species of invertebrates previously unknown to science. Unlike shallow-water corals, which rely heavily on photosynthetic algae for energy, these deep-water corals obtain nutrients primarily through filter-feeding on organic particles carried by ocean currents. The researchers note that the biodiversity of these deep reefs may rival that of their shallow counterparts, challenging the long-held assumption that species richness declines uniformly with depth.', $lyceon_json$[{"key":"A","text":"Deep-water coral reefs near Mauritania have been found to support a surprising level of biodiversity, contradicting expectations about life at extreme depths."},{"key":"B","text":"Shallow-water corals are more dependent on photosynthetic algae than deep-water corals, which prefer filter-feeding strategies."},{"key":"C","text":"Marine biologists have recently cataloged every invertebrate species living in deep-water reefs off the Mauritanian coast."},{"key":"D","text":"Ocean currents are the primary factor determining where deep-water coral reefs can form and sustain themselves."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the discovery that deep-water coral reefs near Mauritania harbor numerous unknown species and may rival shallow reefs in biodiversity, overturning prior assumptions — making the option about surprising biodiversity at extreme depths the best statement of the main idea. The option about photosynthetic algae versus filter-feeding captures a supporting detail rather than the central point. The option claiming every species has been cataloged overstates the findings, since the passage says ''at least seventeen species'' were found, not that a complete inventory was achieved. The option about ocean currents determining reef formation misrepresents the passage, which mentions currents only as a nutrient-delivery mechanism, not as a factor in reef location.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DTH6MK', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Marisol Tenorio has documented how, during the 1930s, Chilean muralists adapted Mexican muralism''s monumental scale but rejected its overtly revolutionary iconography in favor of pastoral and mythological themes drawn from Mapuche oral traditions. Many art historians have treated this adaptation as evidence that Chilean muralism was a diluted imitation of its Mexican predecessor. _______ Tenorio contends that the Chilean muralists'' substitution was itself a political act: by centering Indigenous narratives that the Chilean state had actively suppressed, these artists mounted a critique of national cultural policy that was, in its local context, no less radical than the Mexican movement''s explicit socialism.', $lyceon_json$[{"key":"A","text":"To that end,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"In fact,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank presents many art historians'' view that Chilean muralism was a diluted imitation, while the sentence after the blank presents Tenorio''s opposing interpretation that the substitution was itself a radical political act. "By contrast," correctly signals this direct opposition between the prevailing scholarly view and Tenorio''s reinterpretation. "To that end," implies that Tenorio''s argument serves or furthers the art historians'' characterization, when in fact she disputes it. "In fact," can signal correction but more precisely introduces a factual clarification or intensification of the same line of reasoning; here, however, the shift is between two competing interpretive frameworks rather than a factual correction. "Meanwhile," suggests two events occurring simultaneously rather than two scholars disagreeing about the same phenomenon.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EQ8LND', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In 2019, archaeologists excavating a Bronze Age settlement in central Anatolia uncovered a cache of 41 clay tablets inscribed with a previously undocumented writing system. The symbols bore no resemblance to contemporaneous Hittite cuneiform or Luwian hieroglyphs, and initial attempts to identify loan signs from neighboring scripts were unsuccessful. However, statistical analysis of symbol frequency distributions revealed patterns strikingly similar to those observed in known syllabic writing systems, leading the research team to propose that ________', $lyceon_json$[{"key":"A","text":"the tablets were likely used for decorative purposes rather than for recording language."},{"key":"B","text":"the undocumented script probably represents a syllabic writing system used by a community distinct from the Hittite and Luwian populations."},{"key":"C","text":"Hittite cuneiform was derived from this earlier, previously unknown script rather than from Mesopotamian sources."},{"key":"D","text":"the symbols on the tablets are random marks produced during the manufacturing process for the clay objects."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that the symbols share frequency patterns with known syllabic scripts and bear no resemblance to Hittite or Luwian writing, logically supporting the conclusion that the tablets contain a syllabic script from a distinct community. The option about decorative purposes contradicts the statistical evidence of language-like frequency patterns. The option claiming Hittite cuneiform derived from this script goes far beyond what the evidence supports — the passage mentions no chronological or genealogical relationship between the scripts. The option suggesting random manufacturing marks directly contradicts the finding that the symbols exhibit systematic frequency distributions characteristic of writing systems.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F2B0J5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The advisory board recommended that the municipality _____ its zoning regulations to permit mixed-use development along the riverfront corridor, a proposal that would allow residential units above ground-floor retail spaces for the first time in the district''s history.', $lyceon_json$[{"key":"A","text":"revises"},{"key":"B","text":"revised"},{"key":"C","text":"revise"},{"key":"D","text":"will revise"}]$lyceon_json$::jsonb, 'C', NULL, E'The verb "recommended" followed by "that" introduces a subjunctive clause. In Standard English, the subjunctive mood requires the base form of the verb regardless of the subject. Because "the municipality" is the subject of this subjunctive clause, the correct form is the bare infinitive "revise," not a conjugated form. The third-person singular present indicative "revises" would be appropriate in a declarative statement but is incorrect in a subjunctive clause following "recommended that." The past-tense "revised" incorrectly shifts the clause into the indicative past. The future "will revise" incorrectly introduces a modal auxiliary into a subjunctive construction, which requires the uninflected base form.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FZKWP6', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason Kovalenko''s findings were initially met with skepticism?', E'In 1987, Ukrainian crystallographer Halyna Kovalenko reported synthesizing a stable quasicrystalline alloy at ambient pressure using a mixture of aluminum, cobalt, and nickel with an unusual 73:18:9 atomic ratio. Her results contradicted the prevailing theoretical models, which held that quasicrystals could form only under rapid-cooling conditions or extreme pressures. Because Kovalenko''s laboratory lacked the electron microscopy equipment considered standard for verifying quasicrystalline structures, other researchers questioned whether her samples truly exhibited the five-fold rotational symmetry characteristic of quasicrystals. It was not until 1994, when a visiting team from a German institute examined her archived samples with high-resolution transmission electron microscopy, that the quasicrystalline nature of the alloy was confirmed.', $lyceon_json$[{"key":"A","text":"Kovalenko used an atomic ratio that other researchers considered implausible for producing any crystalline structure."},{"key":"B","text":"Kovalenko's laboratory did not have the equipment regarded as necessary to confirm the structure she claimed to have produced."},{"key":"C","text":"Kovalenko's alloy contained cobalt, a metal not previously associated with quasicrystal formation."},{"key":"D","text":"The German institute that later confirmed her work had initially published a rebuttal of her 1987 paper."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage states that other researchers questioned Kovalenko''s results because her laboratory lacked the electron microscopy equipment considered standard for verifying quasicrystalline structures, making the option about insufficient verification equipment the correct answer. The option about the atomic ratio being considered implausible goes beyond the text — the passage notes the ratio was unusual but attributes skepticism specifically to the equipment gap, not to doubts about the ratio itself. The option about cobalt not being associated with quasicrystals is unsupported; the passage never claims cobalt was a problematic ingredient. The option about the German institute publishing a rebuttal fabricates an event not mentioned anywhere in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GIJDT4', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "tempered" most nearly means', E'Although the initial laboratory results were promising, the principal investigator tempered her enthusiasm during the grant review presentation. She emphasized that the sample consisted of only nineteen participants and that three of the five biomarkers measured had failed to reach statistical significance at the pre-registered threshold.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"moderated"},{"key":"C","text":"forged"},{"key":"D","text":"provoked"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes a researcher who had positive results but deliberately restrained her enthusiasm by citing small sample size and lack of statistical significance. "Moderated" correctly captures the act of reducing the intensity of a response or attitude. "Heated" means to raise the temperature of a substance or to make something hotter, which contradicts the passage''s description of the investigator pulling back from enthusiasm. "Forged" means to shape metal by hammering or to fabricate a document, neither of which applies to adjusting the degree of one''s enthusiasm. "Provoked" means to deliberately stimulate anger or a strong reaction, which is the opposite of the restraint the passage describes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GRZBEC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine the conclusion stated in the text?', E'A 2021 analysis of 83 medieval European manuscripts concluded that the transition from insular script to Caroline minuscule in monastic scriptoria was driven primarily by top-down directives from Carolingian political authorities rather than by organic scribal preference. The study''s authors pointed to a strong temporal correlation between the issuance of royal edicts mandating script uniformity and the adoption dates recorded in colophons across monasteries in Gaul, Burgundy, and Lotharingia. The authors argued that this correlation, combined with the abruptness of the transition in most scriptoria, ruled out a gradual, preference-based adoption model.', $lyceon_json$[{"key":"A","text":"Several monasteries in Lotharingia adopted Caroline minuscule three to five years before any known royal edict addressed script uniformity."},{"key":"B","text":"The royal edicts mandating script uniformity were distributed more widely than scholars had previously believed."},{"key":"C","text":"Colophons in manuscripts from Gaul and Burgundy reliably record the date of script adoption with an accuracy of plus or minus two years."},{"key":"D","text":"Insular script continued to be used for decorative initials in some manuscripts even after the adoption of Caroline minuscule for body text."}]$lyceon_json$::jsonb, 'A', NULL, E'The conclusion rests on the claim that royal edicts drove the transition, supported by temporal correlation between edicts and adoption dates. The finding that some monasteries adopted the new script before any known edict would directly undermine the causal direction of this argument, since the effect would precede the supposed cause. The finding about wider distribution of edicts would actually strengthen the conclusion by expanding the reach of political directives. The finding about colophon dating accuracy addresses the reliability of the evidence but does not challenge the conclusion itself — accurate dates could still support or undermine the argument. The finding about continued use of insular script for decorative initials concerns a limited aesthetic holdover that does not address the main claim about what drove the adoption of Caroline minuscule for body text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HA59OE', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which quotation from a literary critic, if true, would most directly support the claim that Hargrove''s later novels departed significantly from the style of her early work?', E'The American novelist Constance Hargrove published her first three books between 1961 and 1968. These early novels were praised for their spare, declarative prose and tightly controlled narratives set in rural Mississippi. After a seven-year hiatus, Hargrove returned with a series of formally experimental works that incorporated fragmented timelines, multiple unreliable narrators, and extensive passages of stream-of-consciousness writing. Some critics viewed this shift as evidence of Hargrove''s artistic growth, while others considered it a betrayal of the qualities that had distinguished her early fiction.', $lyceon_json$[{"key":"A","text":"\"Hargrove's Mississippi settings remained remarkably consistent throughout her career, providing a stable backdrop against which her characters evolved.\""},{"key":"B","text":"\"The disciplined economy of Hargrove's early sentences gave way, in her post-hiatus work, to sprawling interior monologues that would have been unrecognizable to readers of her 1960s fiction.\""},{"key":"C","text":"\"Hargrove's decision to take a seven-year break from publishing was unusual among novelists of her generation, most of whom maintained a steady output.\""},{"key":"D","text":"\"Like many Southern writers of the period, Hargrove drew heavily on Faulkner's influence from the very beginning of her career.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The claim concerns a significant departure in style between Hargrove''s early and later novels. The quotation about disciplined early sentences giving way to sprawling interior monologues directly illustrates such a stylistic shift, making it the strongest support. The quotation about consistent Mississippi settings addresses setting, not style, so it does not support the claim about stylistic departure. The quotation about the seven-year break addresses her publishing schedule, which is irrelevant to whether her style changed. The quotation about Faulkner''s influence from the beginning suggests continuity rather than departure, which would undermine rather than support the claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HF4LJT', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "exercised" most nearly means', E'Confronted with conflicting projections from her fiscal analysts, the governor exercised considerable caution before endorsing the pension reform package. She commissioned an independent actuarial review and delayed her public statement by eleven days, a move that drew criticism from legislators who had expected swift executive action.', $lyceon_json$[{"key":"A","text":"trained physically"},{"key":"B","text":"exerted influence over"},{"key":"C","text":"employed"},{"key":"D","text":"banished"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes the governor deliberately applying caution — commissioning a review and delaying her statement — before making a decision. "Employed" correctly captures the sense of putting a quality or faculty to use. "Trained physically" refers to bodily exertion for fitness, which is incoherent when applied to the abstract concept of caution. "Exerted influence over" means to apply pressure or authority on someone else, but the passage describes the governor applying caution to her own decision-making process, not influencing another party. "Banished" means to expel or drive away, which is the opposite of what the passage describes — the governor embraced caution rather than rejecting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HQ62DT', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The Pacific golden plover (Pluvialis fulva) migrates nonstop from Alaska to Hawaii each autumn, covering approximately 4,800 kilometers over open ocean without rest. Researchers have documented that juvenile plovers making this journey for the first time depart Alaska an average of eleven days after the adults. Because the juveniles have never previously traveled the route and cannot follow the adults who have already departed, scientists believe that ________', $lyceon_json$[{"key":"A","text":"the juveniles rely on an innate navigational mechanism rather than learning the route from experienced adults."},{"key":"B","text":"the juvenile plovers fly at higher altitudes than adults to compensate for their later departure."},{"key":"C","text":"adult plovers deliberately delay some juveniles to reduce competition for food at stopover sites."},{"key":"D","text":"the nonstop flight to Hawaii is less physically demanding for juveniles than for adult plovers."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that juveniles depart well after adults and have never made the trip before, so they cannot learn the route by following experienced birds. The logical completion is that the juveniles must use an innate navigational ability. The option about flying at higher altitudes introduces an unsupported claim with no basis in the passage. The option about adults deliberately delaying juveniles to reduce competition contradicts the passage, which frames the delayed departure as a natural pattern rather than adult intervention. The option about the flight being less demanding for juveniles contradicts reasonable expectations and has no support in the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I4JNQQ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the anthropologist Fatima al-Rashidi examined pottery shards recovered from a site near Muscat, she noticed that several fragments _____ a distinctive blue pigment previously associated only with ceramics produced in Tang Dynasty China.', $lyceon_json$[{"key":"A","text":"contain"},{"key":"B","text":"has contained"},{"key":"C","text":"contained"},{"key":"D","text":"containing"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence describes a past event: Fatima al-Rashidi "examined" and "noticed" are both in the simple past tense. The clause beginning with "that several fragments" requires a verb in the simple past tense to maintain consistent tense with the rest of the narrative. "Contained" correctly provides the past tense form. The present-tense "contain" breaks the established past-tense frame of the sentence. The singular verb phrase "has contained" fails to agree with the plural subject "fragments" and introduces present perfect tense inconsistent with the narrative past. The present participle "containing" creates a sentence fragment because the noun clause beginning with "that several fragments" lacks a finite verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I8UA5H', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Entomologists studying the bioluminescent click beetle Pyrophorus noctilucus have observed that individuals in dense forest environments produce light pulses with a peak wavelength of 546 nanometers (green), while those in open grassland habitats emit pulses peaking at 582 nanometers (yellow-green). The researchers hypothesized that this variation is an adaptive response to differences in ambient light filtering: in forests, green wavelengths penetrate the leaf canopy more efficiently, increasing the signal''s visibility to potential mates, whereas in grasslands, the slightly longer yellow-green wavelength contrasts more sharply with the dominant spectral background of dry grasses.', $lyceon_json$[{"key":"A","text":"Pyrophorus noctilucus beetles raised in laboratory conditions with no vegetation emit light pulses at a wavelength intermediate between 546 and 582 nanometers."},{"key":"B","text":"When forest-dwelling beetles are relocated to grassland environments, their offspring over successive generations shift toward producing 582-nanometer light pulses."},{"key":"C","text":"Grassland populations of Pyrophorus noctilucus have a significantly higher reproductive rate than forest populations regardless of light wavelength."},{"key":"D","text":"The chemical composition of the luciferin molecule in Pyrophorus noctilucus is identical across all populations studied."}]$lyceon_json$::jsonb, 'B', NULL, E'The hypothesis holds that wavelength variation is an adaptive response to habitat-specific light conditions. The finding that relocated forest beetles'' offspring shift toward grassland-typical wavelengths over generations would directly demonstrate adaptation to the new ambient light environment, supporting the hypothesis. The finding about laboratory beetles emitting an intermediate wavelength is suggestive but does not demonstrate adaptation to a specific habitat''s light conditions — it only shows what happens in the absence of vegetation. The finding about higher reproductive rates in grasslands regardless of wavelength would actually undermine the hypothesis by suggesting that wavelength has no fitness consequence. The finding about identical luciferin chemistry addresses the biochemical substrate but not the adaptive mechanism linking wavelength to habitat.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IA7HM2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban planner Claudette Favreaux has argued that converting disused rail corridors into elevated greenways can reduce neighborhood air pollution by channeling prevailing winds through planted canopy zones. Critics, however, have pointed out that the construction phase itself generates significant particulate emissions, sometimes exceeding five years'' worth of the projected air-quality benefit. _______ Favreaux concedes that construction-phase mitigation measures, such as enclosed demolition and electric-powered machinery, are essential for the net environmental case to hold.', $lyceon_json$[{"key":"A","text":"In response,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the blank presents a criticism of Favreaux''s position, and the sentence after the blank shows Favreaux addressing that criticism by conceding the need for construction-phase mitigation. "In response," correctly signals that Favreaux is replying to the critics'' objection. "Similarly," implies a parallel relationship, but Favreaux is not making the same point as the critics; she is reacting to their objection. "Consequently," suggests a causal result, but Favreaux''s concession is a rhetorical reply to criticism, not a logical consequence of the particulate emission data. "For instance," would introduce an example of a previously stated generalization, but Favreaux''s concession is not an illustration of the critics'' point; it is a separate acknowledgment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ICSR8O', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "mounted" most nearly means', E'By the third week of the drought, frustration among the region''s soybean farmers had mounted considerably. County extension agents reported a surge in calls requesting emergency irrigation permits, and two cooperatives filed formal complaints with the state water board.', $lyceon_json$[{"key":"A","text":"climbed onto"},{"key":"B","text":"intensified"},{"key":"C","text":"displayed"},{"key":"D","text":"attached"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes frustration growing over three weeks, with evidence of escalating actions such as emergency permit requests and formal complaints. "Intensified" correctly captures the sense of an emotion increasing in strength over time. "Climbed onto" refers to physically ascending or getting on top of something, which is incoherent when applied to an abstract feeling like frustration. "Displayed" means to exhibit or show publicly, but the passage describes frustration growing in degree, not being put on exhibition. "Attached" means to fasten one thing to another, which has no connection to the passage''s description of an emotion increasing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IE19G8', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the passages, how would Ota most likely respond to Lindgren''s claim?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IQYXIN', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a literature review and wants to highlight an unresolved tension in the existing research without endorsing either side. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JTTPC3', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'The fruit bat Eidolon helvum undertakes one of the longest documented mammalian migrations in sub-Saharan Africa, with colonies traveling up to 2,500 kilometers between dry-season roosts in Zambia and wet-season foraging grounds in the Democratic Republic of the Congo. Ecologists have long assumed that this migration is driven primarily by the availability of fruiting trees, particularly wild figs. However, a 2022 tracking study led by conservation biologist Nkechi Okafor-Mbah fitted 137 bats with GPS transmitters and found that the animals'' routes deviated significantly from the densest concentrations of fig trees, instead following corridors of elevated nocturnal humidity. Okafor-Mbah hypothesized that the bats select routes minimizing evaporative water loss during flight, and that fruit availability, while important at destination sites, is secondary to microclimatic conditions along the transit corridor itself.', $lyceon_json$[{"key":"A","text":"A 2022 tracking study challenges the traditional explanation for the migration routes of the fruit bat Eidolon helvum by suggesting that microclimatic conditions, rather than fruit availability, primarily determine the corridors the bats follow."},{"key":"B","text":"Conservation biologist Nkechi Okafor-Mbah has demonstrated that fruit bats in sub-Saharan Africa migrate exclusively to avoid predators along routes with dense fig tree populations."},{"key":"C","text":"GPS transmitter technology has recently become advanced enough to track the flight patterns of small mammals such as fruit bats over distances exceeding 2,500 kilometers."},{"key":"D","text":"The fruit bat Eidolon helvum is the only mammal known to migrate between Zambia and the Democratic Republic of the Congo during seasonal transitions."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces the migration of Eidolon helvum, notes the traditional explanation based on fruit availability, and then describes Okafor-Mbah''s GPS tracking study showing the bats follow humidity corridors instead. The main idea is that this study challenges the traditional explanation by proposing that microclimatic conditions, not fruit availability, primarily determine migration routes. The option about avoiding predators and following dense fig populations introduces claims not made in the passage — the passage never mentions predators, and the study found routes deviated from fig concentrations. The option about GPS technology focuses on the research tool rather than the study''s findings about bat migration. The option claiming Eidolon helvum is the only mammal migrating between these countries introduces a uniqueness claim not supported by the passage, which describes the migration as one of the longest, not the only one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LPSGXS', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief summary of a scientific discovery for a general audience. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M5C92C', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'Linguists have long observed that pidgin languages — simplified contact languages used for trade between groups with no common tongue — tend to lack inflectional morphology. This observation led many scholars to conclude that grammatical complexity requires generations of native speakers to develop. However, recent fieldwork by sociolinguist Renata Szabo on the Tok Pisin creole of Papua New Guinea has documented an emerging system of verb suffixes that encodes tense and aspect distinctions not present in the original pidgin. Szabo argues that creolization can produce morphological complexity within as few as three generations, far faster than traditional models predict.', $lyceon_json$[{"key":"A","text":"It describes a linguistic phenomenon, presents a prevailing interpretation, and then introduces research that complicates that interpretation"},{"key":"B","text":"It contrasts two rival theories about pidgin languages and declares one superior to the other"},{"key":"C","text":"It traces the historical evolution of Tok Pisin from its origins to its current form"},{"key":"D","text":"It criticizes earlier linguists for failing to study creole languages with sufficient rigor"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first describes an observation about pidgin languages (lack of inflectional morphology), then presents the prevailing scholarly conclusion (complexity requires generations of native speakers), and finally introduces Szabo''s research showing that creolization can produce complexity faster than expected. This three-part structure — phenomenon, prevailing view, complicating evidence — matches the correct choice. Contrasting two rival theories mischaracterizes the passage; there is one prevailing view and one researcher''s new findings, not two established rival camps. Tracing the full historical evolution of Tok Pisin goes beyond the passage, which mentions only one aspect of the creole''s development. Criticizing earlier linguists for insufficient rigor attributes a tone of censure not present in the passage — Szabo''s work complicates, rather than condemns, earlier conclusions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NAU0JN', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Renata Vieira-Santos studied wage negotiations in 29 mid-sized Brazilian manufacturing firms between 2014 and 2020. She found that when firms disclosed detailed financial statements to employee representatives before negotiations, the resulting wage agreements averaged 3.7% above inflation. When firms withheld financial data, agreements averaged 5.1% above inflation. Vieira-Santos noted that in the latter scenario, employee representatives consistently overestimated firm profitability, leading them to set higher initial demands that firms, unwilling to reveal their actual margins, conceded to rather than prolong disputes. She concluded that, counterintuitively, ________', $lyceon_json$[{"key":"A","text":"firms that disclose financial information to employees tend to reach wage agreements more favorable to the employer than firms that maintain financial secrecy."},{"key":"B","text":"wage negotiations in Brazilian manufacturing firms are primarily influenced by inflation rates rather than by firm-level profitability."},{"key":"C","text":"employee representatives who receive detailed financial data are more likely to demand wages above inflation than those who do not."},{"key":"D","text":"mid-sized manufacturing firms in Brazil experienced declining profitability throughout the period from 2014 to 2020."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that disclosure led to lower wage agreements (3.7% above inflation) compared to secrecy (5.1% above inflation), because withholding data caused employees to overestimate profits and make higher demands that firms then conceded. The logical, counterintuitive conclusion is that transparency produces outcomes more favorable to employers. The option about inflation being the primary influence ignores the passage''s central finding that information asymmetry, not inflation, drives the difference. The option about employees with financial data demanding more directly contradicts the data — those employees agreed to lower figures. The option about declining profitability introduces an unsupported claim; the passage provides no information about profitability trends over the period.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RHNABX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an argument for a school policy proposal and wants to emphasize the cost-effectiveness of a new program compared to the existing approach. Which choice most effectively uses information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RSYWXP', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Entomologist Kaoru Deshimaru of Kyoto Sangyo University has spent over a decade cataloging beetle species in the montane forests of Shikoku. Her most recent field survey, completed in 2023, identified thirty-seven species not previously documented in the region. _______ Deshimaru plans to expand her survey to the adjacent Kii Peninsula, where similar forest elevations may harbor additional undocumented populations.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"Building on these results,"},{"key":"C","text":"For example,"},{"key":"D","text":"Admittedly,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank describes a successful survey that yielded thirty-seven new species, and the sentence after the blank describes Deshimaru''s plan to extend that work to a new location. "Building on these results," correctly signals that the next action follows from and extends the prior achievement. "In contrast," incorrectly implies opposition between the Shikoku findings and the Kii Peninsula plan, when in fact the plan is a continuation. "For example," would introduce a specific instance of a general claim, but expanding to a new peninsula is a next step, not an illustration of the previous finding. "Admittedly," introduces a concession, but nothing in the subsequent sentence concedes a weakness or limitation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VGOCHI', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Paleontologist Ingrid Solheim discovered a trove of fossilized seeds in a Cretaceous-era peat deposit, a finding that contradicted prevailing models of prehistoric plant dispersal in subarctic _____ and prompted three major research institutions to revise their climate-vegetation timelines for northern Scandinavia.', $lyceon_json$[{"key":"A","text":"regions;"},{"key":"B","text":"regions,"},{"key":"C","text":"regions"},{"key":"D","text":"regions—"}]$lyceon_json$::jsonb, 'C', NULL, E'The phrase "a finding that contradicted prevailing models of prehistoric plant dispersal in subarctic regions and prompted three major research institutions to revise their climate-vegetation timelines" is a nonrestrictive appositive renaming "a trove of fossilized seeds in a Cretaceous-era peat deposit." Within this appositive, "contradicted" and "prompted" are compound verbs joined by "and." No punctuation should appear before "and" when it joins only two verb phrases (not two independent clauses), so "regions" needs no punctuation after it. A semicolon after "regions" would incorrectly signal the start of a new independent clause, but "prompted" shares its subject with "contradicted." A comma after "regions" would incorrectly separate the two parts of a compound predicate. An em dash after "regions" would also incorrectly break the compound predicate and introduce a fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YG8QMD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Arjun Subramanian has shown that certain deep-sea hydrothermal vents along the Carlsberg Ridge in the Indian Ocean release dissolved iron at concentrations forty-seven times higher than surrounding seawater. This iron fuels phytoplankton blooms hundreds of kilometers downstream, leading some oceanographers to propose that such vents could be harnessed to stimulate carbon drawdown on a large scale. _______ Subramanian cautions that the same vents simultaneously emit hydrogen sulfide at levels toxic to most marine organisms, meaning that any attempt to amplify vent output would likely devastate the very ecosystems that process the captured carbon.', $lyceon_json$[{"key":"A","text":"Nonetheless,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"That said,"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank describes an optimistic proposal to harness hydrothermal vents for carbon drawdown, while the sentence after the blank introduces Subramanian''s cautionary qualification about toxic hydrogen sulfide emissions undermining that proposal. "That said," correctly signals a qualification or caveat that tempers the preceding optimism without fully contradicting the underlying science. "Nonetheless," implies that what follows persists despite a preceding obstacle, but the structure here is reversed: the optimism comes first and the obstacle follows. "Accordingly," suggests a logical consequence that aligns with the previous claim, but Subramanian''s caution complicates rather than follows from the proposal. "Likewise," implies a parallel finding, but the toxic emissions represent a countervailing concern, not a similar one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
